"""Save reviewer-written state rows in chronological order; no autogenerated visual descriptions."""
import json,sys
from pathlib import Path
root=Path(__file__).resolve().parent.parent
vid=sys.argv[1]; sheet=int(sys.argv[2]); va=json.loads((root/'_work'/vid/'visual_auto.json').read_text()); states=va['states'][(sheet-1)*12:sheet*12]
lines=[x for x in sys.stdin.read().splitlines() if x.strip()]; assert len(lines)==len(states),(len(lines),len(states))
p=root/'_pipeline/annotations'/f'{vid}.txt'
existing=p.read_text() if p.exists() else ''
for s,line in zip(states,lines):
 assert len(line.split('|'))==5,line
 if s['state_id'].endswith('.0') or line.split('|')[-1].startswith(('CUT:','FOOTAGE_CUT:')):
  desc=line.split('|')[0]; tech='SCREEN_CAPTURE;MOTION_GRAPHICS' if any(x in line.split('|')[3] for x in ['SS_','CHART_']) else 'STOCK_FOOTAGE;MOTION_GRAPHICS' if 'FOOTAGE_' in line else 'ORIGINAL_DRAWING;MOTION_GRAPHICS'
  existing+=f"# {s['state_id']} reviewer boundary\n#{s['state_id']}|{desc[:100]}|{tech}\n"
 assert not any(x.startswith(s['state_id']+'|') for x in existing.splitlines())
 existing+=s['state_id']+'|'+line+'\n'
p.write_text(existing)
print(vid,'saved sheet',sheet,'states',len(states))
